import test from 'node:test';
import assert from 'node:assert/strict';
import { unique } from '../src/unique.js';

const cases = [
  { name: 'repeated numbers preserve first-occurrence order', input: [3, 1, 3, 2, 1, 4, 2], expected: [3, 1, 2, 4] },
  { name: 'repeated strings preserve first-occurrence order', input: ['pear', 'apple', 'pear', 'banana', 'apple'], expected: ['pear', 'apple', 'banana'] },
  { name: 'mixed values preserve types and order', input: [1, '1', 2, '2', '1', 1, '2', 2, ''], expected: [1, '1', 2, '2', ''] },
  { name: 'empty array', input: [], expected: [] },
  { name: 'singleton number', input: [7], expected: [7] },
  { name: 'singleton string', input: ['hello'], expected: ['hello'] },
  { name: 'all-duplicate numbers', input: [5, 5, 5, 5], expected: [5] },
  { name: 'all-duplicate strings', input: ['', '', ''], expected: [''] },
  { name: 'already-distinct numbers', input: [9, -2, 0, 1.5], expected: [9, -2, 0, 1.5] },
  { name: 'already-distinct strings', input: ['z', 'a', '', 'A', ' '], expected: ['z', 'a', '', 'A', ' '] },
  { name: 'already-distinct mixed values', input: ['1', 1, '0', 0], expected: ['1', 1, '0', 0] },
];

for (const { name, input, expected } of cases) {
  for (const frozen of [false, true]) {
    test(`${name} (${frozen ? 'frozen' : 'mutable'} input)`, () => {
      const xs = input.slice();
      const before = xs.slice();
      if (frozen) Object.freeze(xs);

      const result = unique(xs);

      assert.ok(Array.isArray(result), 'result must be an array');
      assert.notStrictEqual(result, xs, 'result must be a new array');
      assert.deepStrictEqual(result, expected);
      assert.deepStrictEqual(xs, before, 'input contents must remain unchanged');
    });
  }
}

const invalidCases = [
  { name: 'undefined', value: undefined },
  { name: 'null', value: null },
  { name: 'zero', value: 0 },
  { name: 'nonzero number', value: 42 },
  { name: 'empty string', value: '' },
  { name: 'nonempty string', value: 'aba' },
  { name: 'false', value: false },
  { name: 'true', value: true },
  { name: 'plain object', value: {} },
  { name: 'empty array-like object', value: { length: 0 } },
  { name: 'populated array-like object', value: { 0: 'a', 1: 'a', length: 2 } },
];

for (const { name, value } of invalidCases) {
  test(`rejects ${name} with TypeError`, () => {
    assert.throws(() => unique(value), TypeError);
  });
}

